@Transactional(readOnly = true)
public void processLargeDataset() {
    try (Stream<Customer> customerStream = customerRepository.streamAllByStatus(CustomerStatus.ACTIVE)) {
        customerStream
            .filter(c -> c.isEligibleForDiscount())
            .forEach(c -> emailService.sendPromotionalEmail(c));
    }
}
